import React, { useState, useEffect } from 'react';
import { Container, Typography, Grid, Card, CardContent, Button, Box, Chip } from '@mui/material';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const Jobs = () => {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const { currentUser } = useAuth();

  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/jobs');
      setJobs(response.data.jobs);
    } catch (error) {
      console.error('Error fetching jobs:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = async (jobId) => {
    try {
      await axios.post(`http://localhost:5000/api/jobs/${jobId}/apply`);
      alert('Application submitted successfully!');
    } catch (error) {
      alert('Error applying for job: ' + error.response?.data?.error);
    }
  };

  if (loading) {
    return (
      <Container>
        <Typography>Loading jobs...</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Job Opportunities
      </Typography>
      
      <Grid container spacing={3}>
        {jobs.map((job) => (
          <Grid item xs={12} key={job.id}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {job.title}
                </Typography>
                <Typography color="textSecondary" gutterBottom>
                  {job.company?.name}
                </Typography>
                <Typography variant="body2" paragraph>
                  {job.description}
                </Typography>
                
                <Box sx={{ mb: 2 }}>
                  {job.qualifications?.map((qual, index) => (
                    <Chip key={index} label={qual} size="small" sx={{ mr: 1, mb: 1 }} />
                  ))}
                </Box>
                
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="body2" color="textSecondary">
                    Deadline: {new Date(job.deadline).toLocaleDateString()}
                  </Typography>
                  
                  {currentUser?.role === 'student' && (
                    <Button 
                      variant="contained" 
                      onClick={() => handleApply(job.id)}
                    >
                      Apply Now
                    </Button>
                  )}
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
};

export default Jobs;
